import urllib.request
import json
import re
from collections import defaultdict

url = 'https://docs.google.com/spreadsheets/d/1NQU2SGVykYL3n35NgzL78R0fszK0vt5yacNSV151wYI/gviz/tq?tqx=out:json&gid=1781095899'
req = urllib.request.urlopen(url)
text = req.read().decode('utf-8')
json_str = re.sub(r'^[^(]*\((.*)\)[^)]*$', r'\1', text)
data = json.loads(json_str)

rows = data['table']['rows']

def parse_val(cell):
    if not cell:
        return None
    # prefer formatted string 'f' if available because Google Sheets date serialization in gviz can have 0-indexed month in 'v' (e.g. Date(2025,10,11) is Nov 11)
    f = cell.get('f')
    if f:
        m = re.search(r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})', f)
        if m:
            return int(m.group(1)), int(m.group(2)), int(m.group(3))
    v = cell.get('v')
    if v:
        match = re.match(r'Date\((\d+),(\d+),(\d+)\)', str(v))
        if match:
            return int(match.group(1)), int(match.group(2)) + 1, int(match.group(3))
        m2 = re.search(r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})', str(v))
        if m2:
            return int(m2.group(1)), int(m2.group(2)), int(m2.group(3))
    return None

a_counts = defaultdict(int)
n_counts = defaultdict(int)

for row in rows:
    c = row.get('c')
    if not c:
        continue
    if len(c) > 0 and c[0]:
        res = parse_val(c[0])
        if res:
            y, m, d = res
            if y > 2026 or (y == 2026 and m >= 3):
                a_counts[f'{y}-{m:02d}'] += 1

    if len(c) > 13 and c[13]:
        res = parse_val(c[13])
        if res:
            y, m, d = res
            if y > 2026 or (y == 2026 and m >= 3):
                n_counts[f'{y}-{m:02d}'] += 1

print('=== 方式1 (フォーマット文字列 f を基準) ===')
print('A列 (2026年3月以降):')
for k in sorted(a_counts.keys()):
    print(f'  {k}: {a_counts[k]}件')

print('N列 (2026年3月以降):')
for k in sorted(n_counts.keys()):
    print(f'  {k}: {n_counts[k]}件')
"
